import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

// ⚠️ GEMINI API KEY
const GEMINI_API_KEY = ""; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [seciliMekanId, setSeciliMekanId] = useState(null);
  const [veriYukleniyor, setVeriYukleniyor] = useState(true);

  const [muzekartVar, setMuzekartVar] = useState(false);
  const [aiBilgi, setAiBilgi] = useState({ cevap: "", temp: "", durum: "" });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => {
        if (!res.ok) throw new Error("Backend yok");
        return res.json();
      })
      .then(data => {
        setMekanlar(data);
        setVeriYukleniyor(false);
      })
      .catch(err => {
        console.warn("API Hatası", err);
        setVeriYukleniyor(false);
      });
  }, []);

  const kategoriler = {
    "Tarih": mekanlar.filter(m => m.kategori === "Tarih"),
    "Doğa": mekanlar.filter(m => m.kategori === "Doğa"),
    "Eğlence": mekanlar.filter(m => m.kategori === "Eğlence"),
    "Dalış": mekanlar.filter(m => m.kategori === "Dalış"),
    "Tekne": mekanlar.filter(m => m.kategori === "Tekne"),
    "Yemek": mekanlar.filter(m => m.kategori === "Yemek"),
  };

  const kategoriArkaPlanlari = {
    "Tarih": "https://images.unsplash.com/photo-1528164344705-475426870763?q=80&w=2070&auto=format&fit=crop", 
    "Doğa": "https://images.unsplash.com/photo-1433838552652-f9a46b332c40?q=80&w=2070&auto=format&fit=crop", 
    "Eğlence": "https://images.unsplash.com/photo-1566737236500-c8ac43014a67?q=80&w=2070&auto=format&fit=crop", 
    "Dalış": "https://images.unsplash.com/photo-1544551763-46a013bb70d5?q=80&w=2070&auto=format&fit=crop",
    "Tekne": "https://images.unsplash.com/photo-1534008897995-27a23e859048?q=80&w=2070&auto=format&fit=crop",
    "Yemek": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?q=80&w=1974&auto=format&fit=crop", 
  };

  const rotayiHaritadaGoster = () => {
    if (favoriler.length === 0) return alert("Listeniz boş!");
    const duraklar = favoriler.map(m => encodeURIComponent(m.ad)).join('/');
    window.open(`https://www.google.com/maps/dir/Current+Location/${duraklar}`, '_blank');
  };

  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    else setFavoriler([...favoriler, mekan]);
  };

  const askSmartAI = async (mekan) => {
    if (seciliMekanId === mekan.id) { setSeciliMekanId(null); return; }
    setSeciliMekanId(mekan.id);
    setLoading(true);
    try {
      const wRes = await fetch(`http://localhost:5000/api/hava-durumu?lat=${mekan.lat}&lon=${mekan.lon}`);
      const wData = await wRes.json(); 
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });
      const prompt = `Antalya ${mekan.ad} konumundayım. Hava ${wData.sicaklik}°C. Kısa bir ipucu ver.`;
      const result = await model.generateContent(prompt);
      setAiBilgi({ cevap: result.response.text(), temp: wData.sicaklik, durum: wData.durum });
    } catch (err) {
      setAiBilgi({ cevap: "Hava durumu hatası!", temp: "--" });
    } finally { setLoading(false); }
  };

  if (veriYukleniyor) return <div style={{display:'flex', justifyContent:'center', alignItems:'center', height:'100vh', background:'#111827', color:'#38bdf8'}}>🌘 Yükleniyor...</div>;

  return (
    <div style={{ fontFamily: "'Poppins', sans-serif", background: '#000', color: '#e2e8f0' }}>

      <style>{`
        html { scroll-behavior: smooth; }
        .navbar { 
            display: flex; justify-content: space-between; align-items: center; 
            padding: 15px 40px; background: rgba(0, 0, 0, 0.9);
            backdrop-filter: blur(15px); position: sticky; top: 0; z-index: 1000;
            border-bottom: 1px solid rgba(255,255,255,0.1);
        }
        .nav-link {
            color: #cbd5e1; text-decoration: none; font-size: 13px; font-weight: 600;
            padding: 8px 20px; border: 1px solid rgba(255, 255, 255, 0.15);
            border-radius: 50px; background: rgba(255, 255, 255, 0.05); transition: 0.3s;
        }
        .nav-link:hover { color: #fff; border-color: #f97316; background: rgba(249, 115, 22, 0.2); }
        .category-section { position: relative; min-height: 100vh; padding: 60px 40px; background-attachment: fixed; background-size: cover; display: flex; flex-direction: column; justify-content: center; }
        .overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.75); z-index: 1; }
        .section-content { position: relative; z-index: 2; }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 30px; }
        .card { background: rgba(30, 41, 59, 0.85); border-radius: 20px; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); transition: 0.4s; }
        .card:hover { transform: translateY(-10px); border-color: #f97316; }
        .btn-gradient { background: linear-gradient(135deg, #f97316 0%, #fb923c 100%); color: white; border: none; padding: 10px 25px; border-radius: 50px; font-weight: bold; cursor: pointer; }

        /* ✨ YATAY FOOTER STİLİ */
        .footer {
            background: #0a0a0a;
            border-top: 1px solid rgba(255,255,255,0.1);
            padding: 30px 40px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 14px;
            color: #94a3b8;
        }
        .footer-left { display: flex; align-items: center; gap: 20px; }
        .footer-right { display: flex; gap: 30px; }
        .footer-link { color: #38bdf8; text-decoration: none; transition: 0.3s; }
        .footer-link:hover { color: #f97316; }
        .divider { width: 1px; height: 20px; background: rgba(255,255,255,0.2); }
      `}</style>

      <nav className="navbar">
        <div style={{ display:'flex', alignItems:'center', gap:'10px' }}>
            <span style={{fontSize:'28px'}}>🏝️</span>
            <div>
                <div style={{ fontWeight: 800, color: '#38bdf8', fontSize: '18px' }}>ANTALYA</div>
                <div style={{ fontWeight: 400, color: '#f97316', fontSize: '11px' }}>ROTA ASİSTANI</div>
            </div>
        </div>
        <div className="nav-links">
            {Object.keys(kategoriler).map(kat => (
                <a key={kat} href={`#${kat}`} className="nav-link">{kat}</a>
            ))}
        </div>
        <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
            <button onClick={() => setMuzekartVar(!muzekartVar)} className="muzekart-btn" style={{background: muzekartVar ? '#4f46e5' : 'transparent'}}>
              {muzekartVar ? "💳 Müzekart Var" : "💳 Müzekart Yok"}
            </button>
            <button onClick={rotayiHaritadaGoster} className="btn-gradient">Rotayı Çiz 🚀</button>
        </div>
      </nav>

      {Object.keys(kategoriler).map((katAdi) => {
          const mekanListesi = kategoriler[katAdi];
          if (mekanListesi.length === 0) return null;
          return (
            <div key={katAdi} id={katAdi} className="category-section" style={{ backgroundImage: `url(${kategoriArkaPlanlari[katAdi]})` }}>
                <div className="overlay"></div>
                <div className="section-content">
                    <h2 style={{borderLeft:'6px solid #f97316', paddingLeft:'20px', marginBottom:'30px'}}>{katAdi} Rotaları</h2>
                    <div className="grid">
                        {mekanListesi.map(m => (
                            <div key={m.id} className="card">
                                <img src={m.resim} alt={m.ad} style={{width:'100%', height:'200px', objectFit:'cover'}} />
                                <div style={{ padding: '20px' }}>
                                    <h3>{m.ad}</h3>
                                    <p style={{fontSize:'13px', color:'#94a3b8'}}>{m.aciklama}</p>
                                    <div style={{ display: 'flex', gap: '10px', marginTop:'15px' }}>
                                        <button onClick={() => askSmartAI(m)} style={{flex:1, padding:'10px', borderRadius:'8px', background:'#334155', color:'#38bdf8', border:'none', cursor:'pointer'}}>✨ AI İpucu</button>
                                        <button onClick={() => toggleFavori(m)} style={{flex:1, padding:'10px', borderRadius:'8px', background: favoriler.some(f => f.id === m.id) ? '#ef4444' : '#0f766e', color:'white', border:'none', cursor:'pointer'}}>
                                            {favoriler.some(f => f.id === m.id) ? "Çıkar" : "Ekle +"}
                                        </button>
                                    </div>
                                    {seciliMekanId === m.id && (
                                        <div style={{marginTop:'15px', padding:'10px', background:'rgba(0,0,0,0.3)', borderRadius:'10px', borderLeft:'3px solid #38bdf8'}}>
                                            {loading ? "..." : aiBilgi.cevap}
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
          );
      })}

      {/* ✨ YATAY FOOTER EKLEMESİ */}
      <footer className="footer">
        <div className="footer-left">
            <span style={{fontWeight:'800', color:'#38bdf8'}}>ANTALYA ROTA ASİSTANI</span>
            <div className="divider"></div>
            <span>MAKÜ ZTYO - Yönetim Bilişim Sistemleri</span>
        </div>

        <div className="footer-right">
            <span>Yazılım Stajı 2026</span>
            <div className="divider"></div>
            <span>Weblikya Yazılım / Antalya</span>
            <div className="divider"></div>
            <a href="#" className="footer-link">Geliştirici Portfolyosu</a>
        </div>
      </footer>

    </div>
  );
}

export default App;
